  batches:[{id:1,name:"月度第一批",period:"月度",issue:"次月5日",deadline:"次月15日",reminder:"截止日期前2天"},{id:2,name:"月度第二批",period:"月度",issue:"次月15日",deadline:"次月25日",reminder:"截止日期前2天"},{id:3,name:"季度批",period:"季度",issue:"季后当月5日",deadline:"季后当月25日",reminder:"截止日期前2天"}],
